type Token = 'order-created' | 'order-shipped'
const readers: Record<Token, (b: Buffer) => Event> = {
  'order-created': b => JSON.parse(b.toString()) as OrderCreated,
  'order-shipped': b => JSON.parse(b.toString()) as OrderShipped,
}
const raw = msg.headers?.['content-type']
const tok = (Array.isArray(raw) ? raw[0] : raw) as Token | undefined
if (!tok || !(tok in readers)) throw new Error(`unknown message type ${String(tok)}`)
const event = readers[tok](msg.value)
